`CALL_PRECOMPILE` pseudocode:
```ts
function call_precompile(
    bool yParity,
    uint256 r,
    uint256 s,
    bytes32 extra,
    uint64 mingas,
    address to,
    uint256 value,
    address invoker,
    bytes data
) returns (bool) {
    gas_provided = gasleft();
    require(mingas <= gas_provided);
    require(invoker == msg.sender);
    require(value == msg.value);
    signed_data = abi_encode(extra, mingas, to, value, invoker, data);
    address caller = recover(yParity, r, s, keccak256(TYPE || signed_data));
    // NOTE: caller() == caller within the following call
    return to.call(gas_provided, to, value, data, data.length);
}
```
